insert into public.flashcards (id, cert, deck, domain, objective, front, back) values
-- 3.1 High-Performing Storage: core flashcards
('sa-f-400','awssaa','core',3,'3.1',$$What baseline performance does a gp3 EBS volume provide, and how does it differ from gp2?$$,$$gp3 gives a flat 3,000 IOPS and 125 MB/s throughput regardless of volume size, and you can raise IOPS/throughput independently for an extra fee - unlike gp2, whose baseline IOPS (3 per GB) and burst behavior are tied to the volume's size.$$),
('sa-f-401','awssaa','core',3,'3.1',$$What makes io2 Block Express different from standard io2 volumes?$$,$$io2 Block Express is a next-generation architecture supporting up to 256,000 IOPS and 4,000 MB/s throughput with sub-millisecond latency and 99.999% durability - for the most demanding, latency-sensitive database workloads.$$),
('sa-f-402','awssaa','core',3,'3.1',$$What is EBS Multi-Attach and what does it require?$$,$$It lets a single Provisioned IOPS SSD (io1/io2) volume attach to multiple EC2 instances in the same Availability Zone simultaneously - but since EBS doesn't coordinate concurrent writes, the attached instances must run a cluster-aware file system.$$),
('sa-f-403','awssaa','core',3,'3.1',$$When is EC2 instance store the right choice over EBS for performance?$$,$$Instance store offers very high IOPS and low latency using NVMe SSDs physically attached to the host - ideal for temporary caches, buffers, or scratch data, but all data is lost on stop, terminate, or underlying hardware failure.$$),
('sa-f-404','awssaa','core',3,'3.1',$$How does EFS Max I/O performance mode differ from General Purpose mode?$$,$$Max I/O trades slightly higher per-operation latency for much higher aggregate throughput and IOPS, suited to highly parallelized workloads across thousands of EC2 instances; General Purpose (the default) has lower latency and fits most workloads.$$),
('sa-f-405','awssaa','core',3,'3.1',$$What is EFS Elastic throughput mode?$$,$$It automatically scales a file system's throughput up or down instantly to match the workload's actual activity, with no capacity to provision or manage - you pay only for the throughput you use.$$),
('sa-f-406','awssaa','core',3,'3.1',$$When should you use Amazon FSx for Lustre?$$,$$For high-performance computing and machine learning workloads needing a fast, POSIX-compliant file system with sub-millisecond latencies and hundreds of GB/s throughput - it can link directly to an S3 bucket and process objects as files.$$),
('sa-f-407','awssaa','core',3,'3.1',$$What is Amazon FSx for Windows File Server built for?$$,$$A fully managed native Windows file system supporting the SMB protocol and integrating with Microsoft Active Directory - for lift-and-shift Windows applications needing shared file storage with familiar Windows semantics.$$),
('sa-f-408','awssaa','core',3,'3.1',$$What does Amazon FSx for NetApp ONTAP add over the other FSx options?$$,$$Multi-protocol access (NFS, SMB, and iSCSI) to the same data plus NetApp's data management features - snapshots, cloning, deduplication, and compression - useful for mixed Linux/Windows environments migrating from on-premises NetApp storage.$$),
('sa-f-409','awssaa','core',3,'3.1',$$What are the three AWS Storage Gateway types and what does each provide?$$,$$File Gateway (NFS/SMB access to S3 as files), Volume Gateway (iSCSI block volumes, either cached - hot data local with full dataset in S3, or stored - full dataset local with async backup to S3), and Tape Gateway (a virtual tape library backed by S3/Glacier).$$),
('sa-f-410','awssaa','core',3,'3.1',$$How can you scale S3 to sustain a very high request rate for a single bucket?$$,$$S3 automatically scales to thousands of requests per second per prefix; spreading objects across multiple key prefixes multiplies that ceiling further, since S3 partitions internally by prefix rather than by the whole bucket.$$),
('sa-f-411','awssaa','core',3,'3.1',$$What problem does EBS Fast Snapshot Restore (FSR) solve?$$,$$A volume created from a snapshot normally lazy-loads blocks from S3 on first access, adding latency; FSR pre-warms the volume so it delivers full baseline performance immediately on creation.$$),
('sa-f-412','awssaa','core',3,'3.1',$$What does the EBS Elastic Volumes feature let you do?$$,$$Change a live volume's type, size, or provisioned IOPS/throughput without detaching it or taking any downtime - letting you resize or reprovision performance as needs change.$$),
('sa-f-413','awssaa','core',3,'3.1',$$Why would you stripe several EBS volumes together in a RAID 0 array, and what is the trade-off?$$,$$RAID 0 striping combines the IOPS and throughput of multiple volumes into one logical volume for performance beyond a single volume's limit, but it adds no redundancy - losing any one volume in the array loses all the data.$$),
-- 3.1 acronyms and feynman
('sa-a-140','awssaa','acronym',3,'3.1',$$EFS$$,$$Elastic File System - a managed, elastic NFS file system that many EC2 instances across multiple AZs can mount and share concurrently.$$),
('sa-a-141','awssaa','acronym',3,'3.1',$$RAID$$,$$Redundant Array of Independent Disks - striping (RAID 0) multiple EBS volumes boosts performance; mirroring (RAID 1) adds redundancy instead.$$),
('sa-a-142','awssaa','acronym',3,'3.1',$$SSD$$,$$Solid State Drive - the storage medium behind gp2/gp3 and io1/io2 EBS volumes, giving low-latency, high-IOPS random access.$$),
('sa-y-070','awssaa','feynman',3,'3.1',$$Explain why an application that needs dozens of EC2 instances across several Availability Zones to read and write the same set of files should use Amazon EFS rather than a single EBS volume.$$,$$Model answer: An EBS volume attaches to one instance at a time (or, for io1/io2 with Multi-Attach, to several instances but only within one AZ and only with a cluster-aware file system). EFS is a network file system built to be mounted concurrently by thousands of instances across every AZ in a region at once, with standard NFS semantics that any Linux instance already understands - no special clustering software required. If the requirement is genuinely shared file access at scale across AZs, EFS is the fit; EBS is built for single-instance (or same-AZ) block storage.$$),
-- 3.2 High-Performing/Elastic Compute: core flashcards
('sa-f-414','awssaa','core',3,'3.2',$$When should you choose a compute-optimized (C family) EC2 instance?$$,$$For CPU-bound workloads that need a high ratio of vCPU performance to memory - batch processing, media transcoding, high-performance web servers, and scientific modeling.$$),
('sa-f-415','awssaa','core',3,'3.2',$$When should you choose a memory-optimized (R/X family) EC2 instance?$$,$$For workloads that process large in-memory datasets fast - in-memory databases and caches, and real-time big-data analytics - where memory capacity and bandwidth matter more than raw CPU.$$),
('sa-f-416','awssaa','core',3,'3.2',$$When should you choose a storage-optimized (I/D family) EC2 instance?$$,$$For workloads needing very high, low-latency local disk IOPS or dense sequential throughput - distributed NoSQL databases (I family, local NVMe) and distributed file systems like HDFS (D family, dense HDD).$$),
('sa-f-417','awssaa','core',3,'3.2',$$When should you choose an accelerated computing (P/G/Inf/Trn family) EC2 instance?$$,$$For workloads that benefit from hardware accelerators - GPU-based instances (P/G) for machine learning training and graphics, and purpose-built chips (Inf for inference, Trn for training) for cost-efficient ML at scale.$$),
('sa-f-418','awssaa','core',3,'3.2',$$How do burstable (T family) instances handle CPU performance, and what does "Unlimited" mode change?$$,$$T instances earn CPU credits at a baseline rate and spend them to burst above baseline; in standard mode they throttle to baseline once credits run out, while Unlimited mode lets them keep bursting past that, billing the extra vCPU-hours instead.$$),
('sa-f-419','awssaa','core',3,'3.2',$$What performance benefit do AWS Graviton (ARM-based) instances typically offer?$$,$$Better price-performance - often cited around 40% better than comparable x86 instances for many scale-out workloads - because AWS designs the Graviton processor itself for the specific demands of cloud workloads.$$),
('sa-f-420','awssaa','core',3,'3.2',$$What is the AWS Nitro System and why does it improve EC2 performance?$$,$$It offloads virtualization functions (networking, storage, security) from the host CPU to dedicated Nitro hardware/software, freeing almost all of the host's compute and memory for the customer's workload and enabling near-bare-metal performance.$$),
('sa-f-421','awssaa','core',3,'3.2',$$What is the Elastic Fabric Adapter (EFA) used for?$$,$$A network interface for EC2 that enables OS-bypass, low-latency, high-bandwidth communication between instances - required for tightly-coupled HPC applications (MPI) and large-scale distributed machine learning training.$$),
('sa-f-422','awssaa','core',3,'3.2',$$What does Enhanced Networking (via the ENA driver) provide over standard virtualized networking?$$,$$Higher packets-per-second throughput, lower latency, and lower network jitter, by using a more efficient network interface than the default virtualized NIC.$$),
('sa-f-423','awssaa','core',3,'3.2',$$What is an EC2 On-Demand Capacity Reservation, and what problem does it solve?$$,$$It reserves compute capacity for a specific instance type in a specific Availability Zone so it's guaranteed to be available when you launch into it, with no billing-term commitment required - protecting a critical event or DR failover from an "insufficient capacity" error, independent of any Savings Plan or Reserved Instance discount.$$),
('sa-f-424','awssaa','core',3,'3.2',$$What problem do Auto Scaling warm pools solve?$$,$$They keep a pool of pre-initialized instances (stopped or running, outside the group's active capacity) ready to go, so scaling out doesn't have to wait for a brand-new instance's full boot and initialization time - especially valuable when that setup is slow.$$),
('sa-f-425','awssaa','core',3,'3.2',$$What does AWS Lambda provisioned concurrency do?$$,$$It keeps a specified number of execution environments pre-initialized and ready to respond instantly, eliminating cold-start latency for latency-sensitive functions, at the cost of paying for that kept-warm capacity continuously.$$),
('sa-f-426','awssaa','core',3,'3.2',$$What does AWS Lambda reserved concurrency do, and how is it different from provisioned concurrency?$$,$$It sets a fixed ceiling (and guaranteed allocation) of concurrent executions for one function, isolating it from other functions' bursts and from account-wide throttling - unlike provisioned concurrency, it doesn't pre-warm environments or reduce cold starts.$$),
('sa-f-427','awssaa','core',3,'3.2',$$What is a partition placement group and when is it used?$$,$$It spreads instances into logical partitions on distinct racks with separate power and networking, so a single rack failure only affects one partition - used by distributed frameworks like HDFS, Cassandra, and Kafka to align replicas with partitions for fault isolation without losing intra-partition proximity.$$),
-- 3.2 acronyms and feynman
('sa-a-143','awssaa','acronym',3,'3.2',$$EFA$$,$$Elastic Fabric Adapter - an EC2 network interface enabling OS-bypass, low-latency communication for tightly-coupled HPC and ML workloads.$$),
('sa-a-144','awssaa','acronym',3,'3.2',$$ENA$$,$$Elastic Network Adapter - the enhanced-networking driver delivering higher throughput, lower latency, and lower jitter than standard virtualized NICs.$$),
('sa-a-145','awssaa','acronym',3,'3.2',$$EKS$$,$$Elastic Kubernetes Service - a managed Kubernetes control plane for running containerized workloads at scale on AWS.$$),
('sa-y-071','awssaa','feynman',3,'3.2',$$Explain why AWS Graviton (ARM-based) instances can deliver better price-performance than comparable x86 instances for many workloads.$$,$$Model answer: Graviton is a processor AWS designs itself specifically for cloud data-center workloads, rather than a general-purpose chip repurposed for the cloud. That purpose-built design lets AWS optimize the core count, memory bandwidth, and power efficiency for typical scale-out application patterns (web servers, containerized microservices, open-source databases) instead of chasing single-thread performance for legacy desktop workloads. The result is more useful compute per dollar and per watt for workloads that scale horizontally across many cores - though workloads relying on x86-only software or instruction sets still need x86 instances.$$),
-- 3.3 High-Performing Database: core flashcards
('sa-f-428','awssaa','core',3,'3.3',$$What does Amazon RDS Performance Insights show you?$$,$$A visual dashboard of database load, broken down by SQL statement, wait event, user, or host - making it easy to spot exactly what is consuming the database's capacity during a slowdown.$$),
('sa-f-429','awssaa','core',3,'3.3',$$What does RDS storage autoscaling do?$$,$$Automatically increases allocated storage when free space drops below a threshold, avoiding manual resizing, storage-full outages, and the downtime that used to come with manual storage increases.$$),
('sa-f-430','awssaa','core',3,'3.3',$$What are the Aurora writer, reader, and custom endpoints for?$$,$$The writer endpoint always points at the current primary instance; the reader endpoint load-balances read traffic across all Aurora Replicas; a custom endpoint lets you define your own subset of instances (e.g., by instance class) for a specific workload.$$),
('sa-f-431','awssaa','core',3,'3.3',$$What is Aurora Parallel Query?$$,$$It pushes filtering and aggregation down into Aurora's distributed storage layer and parallelizes execution across many storage nodes, letting analytical queries run fast against live OLTP data without a separate ETL to a data warehouse.$$),
('sa-f-432','awssaa','core',3,'3.3',$$What causes a DynamoDB "hot partition" and how does adaptive capacity help?$$,$$A hot partition happens when a poorly distributed partition key sends disproportionate traffic to one partition, throttling requests even though the table overall has capacity; adaptive capacity automatically shifts throughput toward the busy partition to absorb the imbalance.$$),
('sa-f-433','awssaa','core',3,'3.3',$$What is the key structural difference between a DynamoDB Global Secondary Index (GSI) and a Local Secondary Index (LSI)?$$,$$A GSI has its own partition key (and optional sort key) different from the base table, can be added or removed anytime, and has its own capacity; an LSI shares the base table's partition key but uses a different sort key, must be created when the table is created, and shares the table's capacity.$$),
('sa-f-434','awssaa','core',3,'3.3',$$When would you choose Redis over Memcached in ElastiCache?$$,$$When you need data persistence, built-in replication for high availability, richer data structures (sorted sets, lists, hashes), or pub/sub - Memcached is simpler and multi-threaded per node but has none of those features.$$),
('sa-f-435','awssaa','core',3,'3.3',$$How does an ElastiCache (Redis) replication group improve read performance?$$,$$It runs a primary node plus one or more read replicas that asynchronously copy the primary's data, letting you spread read traffic across the replicas the same way RDS read replicas scale a relational database's reads.$$),
('sa-f-436','awssaa','core',3,'3.3',$$What is Amazon MemoryDB for Redis, and how does it differ from ElastiCache for Redis?$$,$$MemoryDB is a durable, Redis-compatible in-memory database - it stores a multi-AZ transactional log so data survives node failures - meant to be used as a primary database, not just a cache the way ElastiCache typically is.$$),
('sa-f-437','awssaa','core',3,'3.3',$$What makes Amazon Redshift fast for analytical queries compared to a row-oriented database?$$,$$Redshift stores data by column and distributes query execution across many nodes in parallel (MPP), so an analytical query only reads the columns it needs and scans them across the whole cluster at once.$$),
('sa-f-438','awssaa','core',3,'3.3',$$What is Aurora I/O-Optimized storage, and when is it worth choosing?$$,$$A storage configuration that eliminates separate per-I/O charges in exchange for a higher instance price - worth it once an application's I/O costs would otherwise exceed roughly 25% of its total Aurora bill, giving more predictable pricing for I/O-intensive workloads.$$),
-- 3.3 acronyms and feynman
('sa-a-146','awssaa','acronym',3,'3.3',$$GSI$$,$$Global Secondary Index - a DynamoDB index with its own partition/sort key, queryable across the entire table, addable after table creation.$$),
('sa-a-147','awssaa','acronym',3,'3.3',$$LSI$$,$$Local Secondary Index - a DynamoDB index sharing the base table's partition key with a different sort key, defined only at table creation.$$),
('sa-y-072','awssaa','feynman',3,'3.3',$$Explain why adding a DynamoDB Global Secondary Index can dramatically improve performance for an access pattern the base table doesn't support.$$,$$Model answer: DynamoDB is fast only when a query can go straight to a partition using its key - "get all orders for customer X" is instant if the base table's partition key is customer ID, but "get all orders with status = pending" would require scanning every partition, which is slow and expensive at scale. A GSI is really a second, automatically-maintained copy of the table's items indexed by a different partition key (here, status) - now that second access pattern becomes a fast, targeted query too. You're trading extra storage and write capacity for the index in exchange for turning an expensive full scan into a cheap, direct lookup.$$),
-- 3.4 High-Performing/Scalable Networking: core flashcards
('sa-f-439','awssaa','core',3,'3.4',$$What does Route 53 latency-based routing optimize for?$$,$$It answers each DNS query with the record in the region that gives that user the lowest measured network latency to your application, based on AWS's latency measurements between locations and regions - not necessarily the physically closest region.$$),
('sa-f-440','awssaa','core',3,'3.4',$$What is Route 53 geolocation routing used for?$$,$$Routing (or restricting) traffic based on the geographic location of the user making the DNS query - useful for localizing content or meeting legal requirements that traffic from a country or continent be served from a specific region.$$),
('sa-f-441','awssaa','core',3,'3.4',$$What does Route 53 geoproximity routing (via Traffic Flow) let you do?$$,$$Route traffic to the resource geographically closest to the user, while letting you apply a "bias" value to expand or shrink the geographic region served by a particular resource - shifting more or less traffic toward it without changing physical location.$$),
('sa-f-442','awssaa','core',3,'3.4',$$What does Route 53 multivalue answer routing provide?$$,$$It returns up to eight healthy, randomly-selected IP addresses per DNS query, giving simple client-side load distribution and health-check-aware failover as a lightweight alternative to a full load balancer.$$),
('sa-f-443','awssaa','core',3,'3.4',$$When should you choose AWS Direct Connect over a VPN for hybrid connectivity?$$,$$When a workload needs consistent, dedicated bandwidth and lower, more predictable latency and jitter than a connection routed over the public internet - Direct Connect is a private physical link, while a VPN still depends on internet-like variability.$$),
('sa-f-444','awssaa','core',3,'3.4',$$What is a Direct Connect Link Aggregation Group (LAG)?$$,$$It bundles multiple Direct Connect connections at the same location into a single logical connection, providing higher aggregate bandwidth and treating the combined links as one for provisioning purposes.$$),
('sa-f-445','awssaa','core',3,'3.4',$$What does AWS Global Accelerator's traffic dial do?$$,$$It lets you gradually shift a percentage of traffic to or away from an endpoint group (e.g., a new region), enabling controlled canary releases or regional migrations without an abrupt cutover.$$),
('sa-f-446','awssaa','core',3,'3.4',$$What problem does CloudFront Origin Shield solve?$$,$$It adds an extra caching layer in front of your origin that consolidates requests from all edge locations, so the origin sees far fewer duplicate fetches for the same object - reducing origin load and improving cache hit consistency.$$),
('sa-f-447','awssaa','core',3,'3.4',$$When would you use CloudFront Functions instead of Lambda@Edge?$$,$$For lightweight, high-volume operations (header manipulation, URL rewrites, simple auth checks) that need sub-millisecond execution at every edge location; Lambda@Edge suits heavier logic that needs a fuller runtime, more execution time, or network/file access.$$),
('sa-f-448','awssaa','core',3,'3.4',$$How does CloudFront's automatic compression improve performance?$$,$$It compresses eligible text-based content (Gzip or Brotli) at the edge before sending it to the viewer, shrinking transfer size and reducing page load latency without any origin-side changes.$$),
('sa-f-449','awssaa','core',3,'3.4',$$What are AWS Local Zones for?$$,$$They extend compute, storage, and select AWS services to metro areas outside a full Region, putting resources physically closer to end users for latency-sensitive applications like real-time gaming, live streaming, or media production.$$),
('sa-f-450','awssaa','core',3,'3.4',$$What is AWS Wavelength designed for?$$,$$It embeds AWS compute and storage inside telecommunications providers' 5G networks, so mobile application traffic reaches AWS resources without leaving the carrier's network - delivering the ultra-low latency mobile edge applications need.$$),
-- 3.4 acronyms and feynman
('sa-a-148','awssaa','acronym',3,'3.4',$$DX$$,$$Direct Connect - a dedicated, private network connection between an on-premises data center and AWS.$$),
('sa-a-149','awssaa','acronym',3,'3.4',$$LAG$$,$$Link Aggregation Group - combines multiple Direct Connect connections into one logical connection for higher bandwidth and resiliency.$$),
('sa-a-150','awssaa','acronym',3,'3.4',$$PoP$$,$$Point of Presence - a CloudFront edge location that caches content physically close to end users.$$),
('sa-y-073','awssaa','feynman',3,'3.4',$$Explain the performance difference between routing traffic through Amazon CloudFront versus AWS Global Accelerator for an application that serves both web pages and a UDP-based game.$$,$$Model answer: CloudFront is a content delivery network built around HTTP(S) - it caches copies of your web content at edge locations, so repeat requests for the same object are served locally without ever reaching your origin; that's a huge win for the web pages. But CloudFront doesn't understand or accelerate arbitrary UDP traffic - it has nothing to cache there. Global Accelerator works at a lower level: it gives you static Anycast IPs and routes any TCP or UDP traffic over AWS's private backbone network to the nearest healthy endpoint, cutting the number of internet hops without caching content. For this mixed application, you'd put the web pages behind CloudFront to get caching, and route the game's UDP traffic through Global Accelerator to get a faster, more reliable path - each service optimizes a different part of the problem.$$),
-- 3.5 High-Performing Data Ingestion/Transformation: core flashcards
('sa-f-451','awssaa','core',3,'3.5',$$What is a Kinesis Data Streams shard, and how does it set throughput?$$,$$A shard is the base throughput unit of a stream, supporting 1 MB/s (or 1,000 records/s) of writes and 2 MB/s of reads; you provision more shards to raise a stream's total ingest/read capacity.$$),
('sa-f-452','awssaa','core',3,'3.5',$$How long does Kinesis Data Streams retain records, and why does that matter?$$,$$By default 24 hours, extendable up to 365 days - the retention window lets multiple consumers read (and, if needed, replay) the same records independently, which is impossible once a message is deleted from a queue like SQS.$$),
('sa-f-453','awssaa','core',3,'3.5',$$What is Kinesis enhanced fan-out?$$,$$It gives each registered consumer its own dedicated 2 MB/s of read throughput per shard (pushed over HTTP/2), instead of consumers sharing one shard's 2 MB/s read capacity - needed when several consumer applications must all process the full stream independently.$$),
('sa-f-454','awssaa','core',3,'3.5',$$What does Amazon Kinesis Data Firehose do that Kinesis Data Streams does not?$$,$$Firehose is a fully managed delivery service - you just point it at a destination (S3, Redshift, OpenSearch, Splunk) and it handles buffering, batching, and delivery automatically, with no shards or consumer code to manage; Data Streams requires you to build the consumer.$$),
('sa-f-455','awssaa','core',3,'3.5',$$How does Kinesis Data Firehose's buffering configuration affect delivery?$$,$$Firehose batches incoming records until either a configured buffer size or buffer interval is reached, whichever comes first, then delivers the batch - a larger buffer/longer interval improves delivery efficiency at the cost of higher end-to-end latency.$$),
('sa-f-456','awssaa','core',3,'3.5',$$What is Firehose's data transformation feature used for?$$,$$It can invoke a Lambda function on each batch of records before delivery - to convert formats (e.g., JSON to Parquet), enrich, or filter records - so the destination receives already-transformed data.$$),
('sa-f-457','awssaa','core',3,'3.5',$$What is Amazon Kinesis Data Analytics (Managed Service for Apache Flink) used for?$$,$$Running real-time SQL or Apache Flink applications directly against a Kinesis (or MSK) stream - computing rolling aggregates, detecting anomalies, or filtering records - without standing up your own stream-processing cluster.$$),
('sa-f-458','awssaa','core',3,'3.5',$$What is Kinesis resharding, and when would you use it?$$,$$Splitting a shard (to add throughput) or merging shards (to reduce cost when throughput needs drop) while the stream keeps running - used to scale a stream's capacity up or down as traffic patterns change.$$),
('sa-f-459','awssaa','core',3,'3.5',$$What is AWS Glue's core ETL capability?$$,$$A serverless Apache Spark-based service that runs extract-transform-load jobs against data in S3, JDBC sources, and more, without you provisioning or managing any Spark cluster.$$),
('sa-f-460','awssaa','core',3,'3.5',$$What is the AWS Glue Data Catalog?$$,$$A central, persistent metadata repository (table names, schemas, partitions) that Glue, Athena, Redshift Spectrum, and EMR can all query against - decoupling "what the data looks like" from any one processing engine.$$),
('sa-f-461','awssaa','core',3,'3.5',$$What does a Glue crawler do?$$,$$It scans a data source (like an S3 bucket), infers the schema and partition structure, and automatically populates or updates the Glue Data Catalog - so you don't have to hand-write table definitions.$$),
('sa-f-462','awssaa','core',3,'3.5',$$What problem do AWS Glue Job Bookmarks solve?$$,$$They track which source data (e.g., which S3 files or database rows) a job has already processed, so re-running the job on a schedule only processes new or changed data instead of reprocessing everything from scratch.$$),
('sa-f-463','awssaa','core',3,'3.5',$$What is AWS Glue DataBrew for?$$,$$A visual, no-code data preparation tool for analysts to explore, clean, and normalize data (handling nulls, outliers, formatting) through a point-and-click interface, without writing Spark or SQL code.$$),
('sa-f-464','awssaa','core',3,'3.5',$$What is AWS Data Pipeline used for?$$,$$An older orchestration service for scheduling and moving/transforming data between AWS services (and on-premises sources) on a recurring basis - largely superseded for new designs by Glue workflows and Step Functions, but still tested as the legacy option.$$),
('sa-f-465','awssaa','core',3,'3.5',$$What does AWS Database Migration Service (DMS) provide for ongoing ingestion, not just one-time migration?$$,$$Continuous, low-downtime replication using change data capture (CDC) - after an initial full load, DMS keeps streaming ongoing source changes to the target, which can double as a near-real-time ingestion pipeline into a data warehouse or lake.$$),
-- 3.5 acronyms and feynman
('sa-a-151','awssaa','acronym',3,'3.5',$$ETL$$,$$Extract, Transform, Load - pulling data from sources, transforming it, and loading it into a target store, e.g. with AWS Glue jobs.$$),
('sa-a-152','awssaa','acronym',3,'3.5',$$KCL$$,$$Kinesis Client Library - a library for building custom Kinesis Data Streams consumers that handles shard discovery, load balancing, and checkpointing.$$),
('sa-a-153','awssaa','acronym',3,'3.5',$$MSK$$,$$Managed Streaming for Apache Kafka - a fully managed Apache Kafka service for high-throughput streaming ingestion.$$),
('sa-a-154','awssaa','acronym',3,'3.5',$$DMS$$,$$Database Migration Service - a managed service for one-time or continuous (CDC) replication between databases.$$),
('sa-y-074','awssaa','feynman',3,'3.5',$$Explain when you would choose Kinesis Data Streams over Kinesis Data Firehose for an ingestion pipeline.$$,$$Model answer: Firehose is the right default when you just need data to land somewhere - S3, Redshift, OpenSearch, Splunk - reliably and with minimal setup; it handles buffering and delivery for you and you write no consumer code. Data Streams is the choice once you need more control than "deliver it": multiple independent applications reading the same data in real time, custom low-latency processing logic per record, the ability to replay records from earlier in the stream, or sub-second processing that Firehose's buffering delay would prevent. In short: Firehose for "get it there simply," Data Streams for "let me build custom real-time consumers against it."$$),
('sa-y-075','awssaa','feynman',3,'3.5',$$Explain how AWS Glue's crawler and Data Catalog work together to make raw S3 data queryable without writing a manual schema.$$,$$Model answer: You point a crawler at an S3 location; it samples the files, infers their format and column types, detects partitioning from the folder structure, and writes that as a table definition into the Glue Data Catalog. From that point on, the Data Catalog holds the schema, and any compatible engine - Athena, Redshift Spectrum, a Glue ETL job, or EMR - can query the S3 data as if it were a normal table, using the catalog's metadata instead of you hand-writing a CREATE TABLE statement or keeping a schema in sync manually as files change.$$);

insert into public.questions (id, cert, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
-- 3.1 High-Performing Storage
('sa-q-400','awssaa',3,'3.1','mcq',1,$q$A team needs an EBS volume for a general-purpose application database and wants to size IOPS and throughput independently of the volume's capacity, without paying for unused space just to get more performance. Which volume type fits?$q$,$q$["gp2 General Purpose SSD","gp3 General Purpose SSD","st1 Throughput Optimized HDD","sc1 Cold HDD"]$q$::jsonb,'1'::jsonb,$q$gp3 decouples IOPS and throughput from volume size, letting you provision the performance you need directly and cheaply; gp2's performance scales (and is capped) by size, and the HDD types target sequential throughput, not general-purpose IOPS.$q$),
('sa-q-401','awssaa',3,'3.1','mcq',2,$q$A financial trading database needs the highest possible IOPS, the lowest possible latency, and the strongest EBS durability available. Which volume type is the best fit?$q$,$q$["gp3 General Purpose SSD","io1 Provisioned IOPS SSD","io2 Block Express","st1 Throughput Optimized HDD"]$q$::jsonb,'2'::jsonb,$q$io2 Block Express supports up to 256,000 IOPS and 4,000 MB/s at sub-millisecond latency with 99.999% durability - the top tier for latency- and durability-critical databases. gp3 and standard io1 top out well below that, and st1 targets throughput, not IOPS.$q$),
('sa-q-402','awssaa',3,'3.1','multi',2,$q$A team wants to attach one io2 volume to several EC2 instances in the same Availability Zone at the same time for a clustered application. Which statements about this design are true? (Select all that apply.)$q$,$q$["This requires EBS Multi-Attach, supported only on io1/io2 volumes","The attached instances must run a cluster-aware file system, since EBS does not coordinate concurrent writes","Multi-Attach works across multiple Availability Zones","Any EBS volume type supports Multi-Attach"]$q$::jsonb,$q$[0,1]$q$::jsonb,$q$Multi-Attach is an io1/io2-only feature limited to instances within one AZ, and because EBS itself does not arbitrate simultaneous writes from multiple attachers, the application layer needs a cluster-aware file system to avoid corruption. It does not span AZs, and gp2/gp3/HDD volumes don't support it.$q$),
('sa-q-403','awssaa',3,'3.1','mcq',2,$q$A workload writes large volumes of temporary scratch data that can be regenerated if lost, and needs the highest possible local disk IOPS with the lowest latency. What is the best storage choice?$q$,$q$["An EBS gp3 volume","EC2 instance store","S3 Standard","EFS Standard"]$q$::jsonb,'1'::jsonb,$q$Instance store NVMe SSDs deliver very high IOPS and low latency because they're physically attached to the host, ideal for regenerable scratch data - but the data disappears on stop, terminate, or hardware failure, so it must never hold anything irreplaceable.$q$),
('sa-q-404','awssaa',3,'3.1','mcq',2,$q$A media-processing pipeline mounts the same EFS file system from thousands of EC2 instances simultaneously, all reading and writing small files in parallel, and needs the highest aggregate throughput even if individual operations are a bit slower. Which EFS performance mode fits?$q$,$q$["General Purpose","Max I/O","Bursting throughput mode","Provisioned throughput mode"]$q$::jsonb,'1'::jsonb,$q$Max I/O is built for exactly this: massively parallel access from many instances, trading a small increase in per-operation latency for much higher aggregate throughput and IOPS. General Purpose favors low latency for more typical workloads; throughput modes are a separate setting from performance mode.$q$),
('sa-q-405','awssaa',3,'3.1','mcq',1,$q$An EFS file system's usage varies unpredictably throughout the day, and the team doesn't want to provision or monitor throughput manually. Which throughput mode fits?$q$,$q$["Bursting throughput mode","Provisioned throughput mode","Elastic throughput mode","Max I/O performance mode"]$q$::jsonb,'2'::jsonb,$q$Elastic throughput mode automatically scales up or down instantly to match actual workload demand with no provisioning, ideal for unpredictable access patterns. Bursting ties throughput to storage size and credit balance, Provisioned requires a fixed value, and Max I/O is a performance mode, not a throughput mode.$q$),
('sa-q-406','awssaa',3,'3.1','mcq',2,$q$A machine learning team needs a POSIX-compliant, sub-millisecond-latency file system backed by their existing S3 data lake to feed a distributed training job. Which service fits best?$q$,$q$["Amazon FSx for Lustre","Amazon FSx for Windows File Server","Amazon EFS Standard","AWS Storage Gateway File Gateway"]$q$::jsonb,'0'::jsonb,$q$FSx for Lustre is purpose-built for HPC/ML workloads, offering sub-millisecond latencies, very high throughput, and native linking to S3 so objects can be processed as files. FSx for Windows targets SMB/Windows workloads, and EFS/File Gateway don't match Lustre's HPC-grade performance.$q$),
('sa-q-407','awssaa',3,'3.1','matching',2,$q$Match each Amazon FSx file system to the workload it is purpose-built for.$q$,$q${"left":["Amazon FSx for Lustre","Amazon FSx for Windows File Server","Amazon FSx for NetApp ONTAP"],"right":["HPC/ML training needing sub-millisecond latency, often linked to S3","Lift-and-shift Windows applications needing SMB shares and Active Directory integration","Multi-protocol (NFS/SMB/iSCSI) access with NetApp snapshots, cloning, and deduplication"]}$q$::jsonb,$q$[0,1,2]$q$::jsonb,$q$Lustre targets HPC/ML performance; Windows File Server targets native SMB/AD workloads; NetApp ONTAP adds multi-protocol access and NetApp's storage-efficiency features for teams migrating from on-premises NetApp systems.$q$),
('sa-q-408','awssaa',3,'3.1','matching',2,$q$Match each AWS Storage Gateway type to its function.$q$,$q${"left":["File Gateway","Volume Gateway (cached mode)","Tape Gateway"],"right":["Presents S3 as NFS/SMB file shares","Keeps frequently used data cached locally while storing the full dataset in S3","Presents a virtual tape library backed by S3 and Glacier"]}$q$::jsonb,$q$[0,1,2]$q$::jsonb,$q$File Gateway serves S3 objects as files over NFS/SMB; cached-mode Volume Gateway keeps hot data local (low latency) while the authoritative full dataset lives in S3; Tape Gateway emulates physical tape infrastructure for backup software, backed by S3/Glacier.$q$),
('sa-q-409','awssaa',3,'3.1','mcq',2,$q$An application performs an extremely high volume of GET requests against a single S3 bucket and starts seeing throttling. All requests use the same object key prefix. What is the most effective way to raise the sustainable request rate?$q$,$q$["Enable S3 Versioning","Spread objects across multiple key prefixes so S3 partitions the load","Switch the bucket to S3 One Zone-IA","Enable Cross-Region Replication"]$q$::jsonb,'1'::jsonb,$q$S3 scales request rates per prefix; concentrating all traffic on one prefix caps throughput at that prefix's ceiling, while distributing objects across several prefixes lets S3 parallelize and multiplies the sustainable rate. Versioning, storage class, and replication don't address request-rate partitioning.$q$),
('sa-q-410','awssaa',3,'3.1','ordering',2,$q$Order these S3/Glacier storage options from FASTEST to SLOWEST typical object retrieval time.$q$,$q$["S3 Standard","S3 Glacier Instant Retrieval","S3 Glacier Flexible Retrieval","S3 Glacier Deep Archive"]$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$S3 Standard serves objects with immediate, millisecond access; Glacier Instant Retrieval also offers millisecond access but at colder-tier pricing; Glacier Flexible Retrieval takes minutes to hours depending on the retrieval tier chosen; Deep Archive is the slowest, taking hours, in exchange for being the cheapest.$q$),
('sa-q-411','awssaa',3,'3.1','mcq',2,$q$A team restores a large database from an EBS snapshot and finds the first several hours of access are noticeably slower than normal, before performance settles. What feature prevents this?$q$,$q$["Elastic Volumes","Fast Snapshot Restore (FSR)","EBS Multi-Attach","RAID 0 striping"]$q$::jsonb,'1'::jsonb,$q$A snapshot-restored volume normally lazy-loads blocks from S3 on first touch, causing a slow warm-up period; Fast Snapshot Restore pre-initializes the volume so it delivers full performance immediately. Elastic Volumes, Multi-Attach, and RAID striping solve different problems.$q$),
('sa-q-412','awssaa',3,'3.1','mcq',1,$q$A production database's EBS volume was provisioned as gp3 but now needs to move to io2 for higher IOPS. The team cannot tolerate downtime. What lets them do this?$q$,$q$["Detach the volume, delete it, and recreate it as io2","Use the Elastic Volumes feature to modify the volume's type in place","Take a snapshot and restore it to a new instance","This change is not possible without downtime"]$q$::jsonb,'1'::jsonb,$q$Elastic Volumes lets you change a live volume's type, size, or provisioned performance without detaching it or taking downtime. Deleting/recreating or snapshot-and-restore both require an outage or a cutover.$q$),
('sa-q-413','awssaa',3,'3.1','mcq',2,$q$A data-warehouse load job needs more aggregate IOPS and throughput than a single EBS volume can provide, and the data itself is already durably backed up elsewhere on a schedule. What is a reasonable way to increase raw storage performance?$q$,$q$["Stripe multiple EBS volumes together using RAID 0","Mirror two EBS volumes using RAID 1","Enable EBS Multi-Attach on a single gp3 volume","Switch to S3 Standard for block storage"]$q$::jsonb,'0'::jsonb,$q$RAID 0 striping combines multiple volumes' IOPS and throughput into one logical volume, raising performance beyond any single volume's ceiling - an acceptable trade-off here since durability is already handled by backups; RAID 0 itself adds no redundancy. RAID 1 mirrors for redundancy, not performance; Multi-Attach isn't a striping mechanism; and S3 isn't block storage.$q$),
-- 3.2 High-Performing/Elastic Compute
('sa-q-414','awssaa',3,'3.2','mcq',1,$q$A batch video-transcoding service is entirely CPU-bound and needs the best possible price-performance for raw compute. Which EC2 instance family fits?$q$,$q$["Memory optimized (R family)","Compute optimized (C family)","Storage optimized (I family)","Burstable (T family)"]$q$::jsonb,'1'::jsonb,$q$Compute-optimized C-family instances maximize vCPU performance per dollar for CPU-bound work like transcoding. Memory- and storage-optimized families target different bottlenecks, and burstable T instances aren't meant for sustained, heavy CPU load.$q$),
('sa-q-415','awssaa',3,'3.2','mcq',1,$q$A real-time analytics application holds a very large working dataset entirely in memory for fast lookups. Which EC2 instance family should it run on?$q$,$q$["Compute optimized (C family)","Memory optimized (R/X family)","Storage optimized (D family)","Accelerated computing (P family)"]$q$::jsonb,'1'::jsonb,$q$Memory-optimized R/X instances provide the largest memory capacity and bandwidth per instance, suited to in-memory databases and caches with large working sets. C, D, and P families target CPU, dense disk, and GPU workloads instead.$q$),
('sa-q-416','awssaa',3,'3.2','mcq',2,$q$A distributed NoSQL database needs very high, low-latency local disk IOPS on each node. Which EC2 instance family is the best fit?$q$,$q$["Storage optimized (I family) with local NVMe","Memory optimized (R family)","Burstable (T family)","Accelerated computing (G family)"]$q$::jsonb,'0'::jsonb,$q$The I family provides high-performance local NVMe storage tuned for exactly this random-IOPS, low-latency pattern used by distributed NoSQL databases. The other families target memory capacity, burstable low-cost compute, and graphics/ML acceleration respectively.$q$),
('sa-q-417','awssaa',3,'3.2','mcq',1,$q$A team is training a deep learning model and needs GPU acceleration. Which EC2 instance family should they choose?$q$,$q$["General purpose (M family)","Storage optimized (D family)","Accelerated computing (P family)","Burstable (T family)"]$q$::jsonb,'2'::jsonb,$q$The P family provides GPU acceleration purpose-built for machine learning training and other highly parallel numerical workloads. M, D, and T families don't include GPU hardware.$q$),
('sa-q-418','awssaa',3,'3.2','mcq',2,$q$A T3 instance running a lightweight web service repeatedly exhausts its CPU credit balance during traffic spikes, causing throttling in standard mode. What lets it keep bursting past its baseline instead of throttling?$q$,$q$["Switching the instance to Unlimited mode","Attaching an Elastic Fabric Adapter","Enabling EBS Multi-Attach","Moving to a partition placement group"]$q$::jsonb,'0'::jsonb,$q$T3 Unlimited mode allows the instance to sustain CPU bursts above baseline indefinitely, billing the extra usage instead of throttling once credits run out. EFA, Multi-Attach, and placement groups don't affect CPU credit behavior.$q$),
('sa-q-419','awssaa',3,'3.2','mcq',1,$q$A company wants to reduce compute cost for a horizontally-scaled, containerized web application without materially changing its architecture. Which EC2 instance option is most likely to improve price-performance?$q$,$q$["Switching from Graviton (ARM) instances to comparable x86 instances","Switching from comparable x86 instances to Graviton (ARM) instances","Switching from On-Demand to Dedicated Hosts","Disabling enhanced networking"]$q$::jsonb,'1'::jsonb,$q$Graviton processors typically offer notably better price-performance than comparable x86 instances for scale-out, containerized workloads. Moving away from Graviton, switching to Dedicated Hosts, or disabling enhanced networking would not improve (and could worsen) price-performance here.$q$),
('sa-q-420','awssaa',3,'3.2','mcq',2,$q$An architect wants EC2 instances that deliver performance close to bare metal by offloading virtualization overhead (networking, storage, security) away from the host CPU. What makes this possible on modern EC2 instances?$q$,$q$["The AWS Nitro System","EBS Multi-Attach","Auto Scaling warm pools","AWS Glue"]$q$::jsonb,'0'::jsonb,$q$The Nitro System moves virtualization functions to dedicated Nitro hardware/software, leaving nearly all host CPU and memory available to the customer's workload for near-bare-metal performance. The other options address storage attachment, scaling readiness, and ETL - unrelated to virtualization offload.$q$),
('sa-q-421','awssaa',3,'3.2','mcq',3,$q$A tightly-coupled HPC application uses MPI across many EC2 instances and is bottlenecked by inter-node network latency, not raw CPU. What should be added to the instances to address this?$q$,$q$["Elastic Fabric Adapter (EFA)","A larger EBS volume","EBS Multi-Attach","S3 Transfer Acceleration"]$q$::jsonb,'0'::jsonb,$q$EFA provides OS-bypass, low-latency, high-bandwidth networking between instances, specifically built for tightly-coupled HPC/MPI and distributed ML training bottlenecked by inter-node communication. The other options address storage, not inter-instance networking.$q$),
('sa-q-422','awssaa',3,'3.2','mcq',2,$q$An application experiences inconsistent network latency and jitter between EC2 instances using the default virtualized network interface. Which feature reduces this?$q$,$q$["Enhanced networking (ENA)","EBS Elastic Volumes","Lambda provisioned concurrency","S3 Intelligent-Tiering"]$q$::jsonb,'0'::jsonb,$q$Enhanced networking via the ENA driver delivers higher packet-per-second throughput with lower, more consistent latency and jitter than the default virtualized NIC. The other options address storage resizing, Lambda cold starts, and S3 cost - not instance-to-instance networking.$q$),
('sa-q-423','awssaa',3,'3.2','mcq',2,$q$A team must guarantee that 50 specific EC2 instances will be available to launch in a particular Availability Zone during a scheduled disaster-recovery failover test next month, and wants this guarantee without committing to a 1- or 3-year billing term. What should they use?$q$,$q$["A Compute Savings Plan","An On-Demand Capacity Reservation","A Spot Instance request","A cluster placement group"]$q$::jsonb,'1'::jsonb,$q$A Capacity Reservation guarantees that capacity for a specific instance type and AZ is available when needed, with no term commitment - exactly matching a guaranteed-availability need without a billing commitment. Savings Plans discount cost but don't guarantee capacity, Spot capacity can be reclaimed, and a placement group affects instance layout, not capacity guarantees.$q$),
('sa-q-424','awssaa',3,'3.2','mcq',2,$q$An Auto Scaling group's instances take several minutes to become ready due to a lengthy application initialization process, causing slow response to sudden traffic spikes. What reduces this scale-out latency?$q$,$q$["Auto Scaling warm pools","EBS Fast Snapshot Restore","Lambda reserved concurrency","A cluster placement group"]$q$::jsonb,'0'::jsonb,$q$Warm pools keep pre-initialized instances ready outside the group's active capacity, so scaling out can add already-initialized instances instead of waiting for a full cold boot and setup. The other options address snapshot performance, Lambda concurrency limits, and network placement, not ASG launch latency.$q$),
('sa-q-425','awssaa',3,'3.2','multi',2,$q$Which of the following statements about AWS Lambda concurrency controls are TRUE? (Select all that apply.)$q$,$q$["Provisioned concurrency keeps execution environments pre-initialized to eliminate cold starts","Reserved concurrency guarantees and caps the number of concurrent executions for one function","Provisioned concurrency is free and has no additional cost beyond normal invocation billing","Reserved concurrency pre-warms execution environments the same way provisioned concurrency does"]$q$::jsonb,$q$[0,1]$q$::jsonb,$q$Provisioned concurrency pre-initializes environments to remove cold-start latency, and reserved concurrency sets a dedicated ceiling (and guaranteed minimum) of concurrent executions for a function - but provisioned concurrency is billed for the kept-warm capacity even when idle, and reserved concurrency does not pre-warm anything; it only limits/guarantees a concurrency count.$q$),
('sa-q-426','awssaa',3,'3.2','matching',2,$q$Match each compute feature to what it is used for.$q$,$q${"left":["AWS Lambda SnapStart","AWS Batch","AWS App Runner","EC2 Hibernate"],"right":["Snapshots an initialized Java execution environment to cut cold-start time","Dynamically provisions the optimal compute for submitted batch jobs, no server management","Fully managed deployment and scaling of containerized web apps/APIs from source or image","Preserves an instance's in-memory state to the EBS root volume for a faster resume than a cold boot"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$SnapStart targets Java cold starts specifically; AWS Batch handles job scheduling and compute provisioning for batch workloads; App Runner is the fastest path to a running containerized web service; EC2 Hibernate preserves RAM state to skip a full OS boot on resume.$q$),
('sa-q-427','awssaa',3,'3.2','ordering',2,$q$Order these ways of getting an EC2 instance ready to serve traffic, from SLOWEST to FASTEST.$q$,$q$["Launching a brand-new On-Demand instance from an AMI","Starting a stopped instance from an Auto Scaling warm pool","An already-running instance behind the load balancer receiving new connections"]$q$::jsonb,$q$[0,1,2]$q$::jsonb,$q$A brand-new launch pays the full boot-and-initialization cost; a warm-pool instance is already initialized and just needs to start, which is faster; an instance already running and healthy behind the load balancer can accept new connections immediately, with no startup delay at all.$q$),
-- 3.3 High-Performing Database
('sa-q-428','awssaa',3,'3.3','mcq',1,$q$A production RDS database slows down intermittently and the team needs to identify exactly which SQL statement or wait event is consuming the most database load. What should they use?$q$,$q$["RDS Performance Insights","RDS storage autoscaling","Amazon Redshift","AWS Glue"]$q$::jsonb,'0'::jsonb,$q$Performance Insights visualizes database load broken down by SQL statement, wait event, user, and host, pinpointing exactly what's consuming capacity. Storage autoscaling manages disk space, not query performance, and Redshift/Glue are unrelated services.$q$),
('sa-q-429','awssaa',3,'3.3','mcq',1,$q$An RDS database has occasionally run out of allocated storage, causing outages, because the team forgets to resize it manually. What prevents this going forward?$q$,$q$["Enabling RDS storage autoscaling","Enabling Multi-AZ","Adding a read replica","Enabling Performance Insights"]$q$::jsonb,'0'::jsonb,$q$Storage autoscaling automatically increases allocated storage when free space drops below a threshold, removing the need for manual resizing and avoiding storage-full outages. Multi-AZ, read replicas, and Performance Insights don't manage storage capacity.$q$),
('sa-q-430','awssaa',3,'3.3','mcq',2,$q$An application scales its Aurora read traffic by adding more Aurora Replicas over time and wants new connections automatically load-balanced across all of them without changing application config for each new replica. Which endpoint should it use?$q$,$q$["The cluster writer endpoint","The reader endpoint","A custom endpoint restricted to one instance","A direct connection to each replica's private IP"]$q$::jsonb,'1'::jsonb,$q$The reader endpoint automatically load-balances connections across all current Aurora Replicas, so adding or removing replicas doesn't require reconfiguring the application. The writer endpoint always targets the primary, and hardcoding individual endpoints defeats automatic load balancing.$q$),
('sa-q-431','awssaa',3,'3.3','mcq',3,$q$An Aurora MySQL cluster runs both transactional application traffic and occasional heavy analytical aggregate queries against the same live tables, and the team wants to avoid building a separate data warehouse just for this. Which Aurora feature helps the analytical queries run fast?$q$,$q$["Aurora Parallel Query","Aurora Global Database","Aurora Serverless v2","RDS Proxy"]$q$::jsonb,'0'::jsonb,$q$Parallel Query pushes filtering and aggregation down into Aurora's distributed storage layer and parallelizes it across storage nodes, speeding up analytical queries against live OLTP data without a separate warehouse. Global Database and Serverless v2 solve cross-region replication and capacity elasticity, not query pushdown; RDS Proxy pools connections.$q$),
('sa-q-432','awssaa',3,'3.3','multi',2,$q$A DynamoDB table is throttling requests to one specific item range even though the table's overall provisioned capacity is far from exhausted. Which of the following would help address this "hot partition" problem? (Select all that apply.)$q$,$q$["Choosing a higher-cardinality partition key that spreads traffic more evenly","Adding a random or calculated suffix to the partition key to shard hot items further","Relying on adaptive capacity to automatically shift throughput toward the busy partition","Simply increasing the table's overall provisioned RCU/WCU without changing the key design"]$q$::jsonb,$q$[0,1,2]$q$::jsonb,$q$A better-distributed partition key and write-sharding both directly fix the underlying skew, and adaptive capacity automatically compensates for imbalance in the meantime. Raising overall table capacity doesn't help if the same narrow partition is still absorbing all the traffic.$q$),
('sa-q-433','awssaa',3,'3.3','mcq',2,$q$A DynamoDB table's base access pattern is efficient, but a new requirement needs queries against an attribute that isn't the base table's partition key, and this new access pattern should be addable without recreating the table. What should be added?$q$,$q$["A Local Secondary Index (LSI)","A Global Secondary Index (GSI)","A second base table with the same data","A DynamoDB Stream"]$q$::jsonb,'1'::jsonb,$q$A GSI has its own partition/sort key and can be added at any time after table creation, fitting a new access pattern without a rebuild. An LSI must be defined at table creation time, and duplicating the table or adding a stream doesn't create a queryable index.$q$),
('sa-q-434','awssaa',3,'3.3','mcq',1,$q$An application caching layer needs automatic failover to a replica if the primary node fails, and must support rich data structures like sorted sets. Which ElastiCache engine fits?$q$,$q$["Memcached","Redis","Both are equivalent here","Neither supports replication"]$q$::jsonb,'1'::jsonb,$q$Redis supports replication with automatic failover and rich data structures (sorted sets, lists, hashes); Memcached is simpler, multi-threaded, and lacks both built-in replication/failover and those richer data types.$q$),
('sa-q-435','awssaa',3,'3.3','mcq',2,$q$A read-heavy application caches session data in a single ElastiCache Redis primary node, which is now the bottleneck for read throughput. What scales read capacity without changing the write path?$q$,$q$["Add Redis read replicas via a replication group and direct reads to them","Switch the primary to Memcached","Disable persistence on the primary node","Increase the number of Availability Zones only"]$q$::jsonb,'0'::jsonb,$q$A Redis replication group's read replicas asynchronously copy the primary and can absorb read traffic, scaling reads the same way RDS read replicas do - without touching how writes reach the primary. Switching engines, disabling persistence, and AZ count alone don't add read capacity.$q$),
('sa-q-436','awssaa',3,'3.3','mcq',2,$q$A team wants an in-memory data store that can act as their application's durable primary database - not just a cache in front of another database - while remaining Redis-compatible. Which service fits?$q$,$q$["Amazon ElastiCache for Redis","Amazon MemoryDB for Redis","Amazon DynamoDB Accelerator (DAX)","Amazon Redshift"]$q$::jsonb,'1'::jsonb,$q$MemoryDB for Redis stores a multi-AZ transactional log so data durably survives node failures, making it suitable as a primary database rather than only a cache. ElastiCache is designed as a cache in front of another data store, DAX only caches DynamoDB, and Redshift is a columnar warehouse, not a key-value store.$q$),
('sa-q-437','awssaa',3,'3.3','mcq',2,$q$An analytics team runs large aggregate queries scanning billions of rows but only a handful of columns each time, and wants a database engine optimized for exactly this pattern. Which is the best fit?$q$,$q$["Amazon RDS MySQL","Amazon DynamoDB","Amazon Redshift","Amazon ElastiCache"]$q$::jsonb,'2'::jsonb,$q$Redshift's columnar storage and massively parallel processing (MPP) let a query read only the needed columns and scan them across many nodes at once - ideal for large aggregate analytical queries. RDS MySQL is row-oriented, DynamoDB is key-value, and ElastiCache is an in-memory cache, not an analytical engine.$q$),
('sa-q-438','awssaa',3,'3.3','matching',3,$q$Match each database feature to the performance characteristic it delivers.$q$,$q${"left":["Aurora I/O-Optimized storage","DynamoDB Accelerator (DAX)","Amazon Redshift Spectrum","Amazon MemoryDB for Redis"],"right":["Predictable pricing for I/O-intensive Aurora workloads by removing per-I/O charges","Microsecond read latency in front of DynamoDB via an in-memory cache","Querying data directly in S3 from a Redshift cluster without loading it first","A durable, Redis-compatible store usable as a primary database, not just a cache"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Each service targets a distinct performance angle: I/O-Optimized storage changes Aurora's pricing model for I/O-heavy apps; DAX caches DynamoDB reads in memory; Redshift Spectrum extends queries into S3 without an ETL load; MemoryDB provides durable in-memory primary storage.$q$),
-- 3.4 High-Performing/Scalable Networking
('sa-q-439','awssaa',3,'3.4','mcq',1,$q$A global application runs identical stacks in three regions and wants each user's DNS query answered with the region that gives that specific user the lowest network latency. Which Route 53 routing policy fits?$q$,$q$["Geolocation routing","Latency-based routing","Weighted routing","Multivalue answer routing"]$q$::jsonb,'1'::jsonb,$q$Latency-based routing answers based on AWS's measured network latency between the user's location and each region, directly optimizing for lowest latency. Geolocation routes by the user's geographic location (not measured latency), weighted splits by assigned proportion, and multivalue answer just returns several healthy IPs.$q$),
('sa-q-440','awssaa',3,'3.4','mcq',2,$q$A company must ensure that users located in the European Union are served only from an EU-based endpoint, for data residency compliance, regardless of which endpoint would otherwise be fastest. Which Route 53 policy fits?$q$,$q$["Latency-based routing","Geolocation routing","Weighted routing","Failover routing"]$q$::jsonb,'1'::jsonb,$q$Geolocation routing routes (or restricts) based on the user's geographic location, letting a company enforce that EU users are only ever served from an EU endpoint - exactly a compliance/data-residency requirement, unlike latency-based routing which would route to whichever region is fastest.$q$),
('sa-q-441','awssaa',3,'3.4','mcq',3,$q$A company serves two regions and wants to shift more traffic toward the newer region without moving it geographically, by expanding the geographic area it's considered to "cover," while still generally favoring the closest region for each user. Which Route 53 feature fits?$q$,$q$["Weighted routing with adjusted weights","Geoproximity routing with a bias value","Simple routing","Multivalue answer routing"]$q$::jsonb,'1'::jsonb,$q$Geoproximity routing (via Traffic Flow) lets you apply a bias to a resource, expanding or shrinking the geographic area routed to it, while still generally favoring the closest resource - directly matching this requirement. Weighted routing shifts traffic by a flat percentage regardless of geography, and simple/multivalue routing don't offer geographic bias.$q$),
('sa-q-442','awssaa',3,'3.4','mcq',2,$q$A team wants a lightweight way for DNS responses to return several healthy endpoint IPs so clients can pick one themselves, plus automatic exclusion of any IP that fails its health check, without deploying a full load balancer. Which Route 53 policy fits?$q$,$q$["Simple routing","Multivalue answer routing","Failover routing","Latency-based routing"]$q$::jsonb,'1'::jsonb,$q$Multivalue answer routing returns multiple healthy, randomly-selected IP addresses per query and excludes unhealthy ones, giving lightweight distribution and failover without a full load balancer. Simple routing returns one static answer, and failover/latency solve different problems.$q$),
('sa-q-443','awssaa',3,'3.4','mcq',2,$q$A financial services company needs a hybrid connection to AWS with consistent, dedicated bandwidth and minimal, predictable latency and jitter for a latency-sensitive trading application, rather than routing over the public internet. What should they use?$q$,$q$["A Site-to-Site VPN over the internet","AWS Direct Connect","A NAT Gateway","CloudFront"]$q$::jsonb,'1'::jsonb,$q$Direct Connect is a dedicated private physical connection, giving consistent bandwidth and much lower, more predictable latency and jitter than a connection routed over the public internet. A VPN still traverses the internet's variability, and NAT Gateway/CloudFront don't provide on-premises connectivity.$q$),
('sa-q-444','awssaa',3,'3.4','mcq',2,$q$A company's single Direct Connect connection has become a bandwidth bottleneck as traffic grows, and they want to combine several physical connections at the same location into one higher-bandwidth logical connection. What should they configure?$q$,$q$["A Direct Connect gateway","A Link Aggregation Group (LAG)","A Transit Gateway","Multiple unrelated VPN tunnels"]$q$::jsonb,'1'::jsonb,$q$A LAG bundles multiple Direct Connect connections at one location into a single logical connection with combined bandwidth. A Direct Connect gateway extends connectivity to multiple regions/VPCs (not bandwidth aggregation), and Transit Gateway/VPN solve different connectivity problems.$q$),
('sa-q-445','awssaa',3,'3.4','mcq',2,$q$A company is migrating traffic to a newly deployed regional endpoint behind AWS Global Accelerator and wants to shift traffic gradually - say 5%, then 25%, then 100% - rather than an abrupt cutover. What Global Accelerator feature enables this?$q$,$q$["Endpoint weights within an endpoint group plus the traffic dial","Route 53 weighted routing instead","A CloudFront cache invalidation","Changing the accelerator's static IP addresses"]$q$::jsonb,'0'::jsonb,$q$Global Accelerator's traffic dial (and per-endpoint weights) let you control what percentage of traffic reaches an endpoint group, enabling a gradual, controlled migration. Route 53 weighted routing is a separate DNS-level mechanism, and cache invalidation or IP changes don't control traffic percentage.$q$),
('sa-q-446','awssaa',3,'3.4','mcq',2,$q$An origin server behind CloudFront is being overwhelmed by many near-duplicate requests for the same rarely-changing object, arriving from dozens of different edge locations around the world. What reduces this origin load?$q$,$q$["Enabling CloudFront Origin Shield","Switching to Application Load Balancer sticky sessions","Adding more edge locations manually","Disabling caching entirely"]$q$::jsonb,'0'::jsonb,$q$Origin Shield adds a consolidating caching layer in front of the origin that all edge locations route through, so the origin sees far fewer duplicate fetches for the same object. The other options don't reduce duplicate origin requests, and disabling caching would make the problem worse.$q$),
('sa-q-447','awssaa',3,'3.4','mcq',2,$q$A team needs to rewrite a request header at every CloudFront edge location on every single request, with the lowest possible added latency and cost, and no need for filesystem or network access in the function. What should they use?$q$,$q$["Lambda@Edge","CloudFront Functions","AWS Step Functions","AWS Glue"]$q$::jsonb,'1'::jsonb,$q$CloudFront Functions are built for exactly this: lightweight, high-volume, sub-millisecond JavaScript operations like header/URL manipulation at every edge location, cheaper and faster than Lambda@Edge. Lambda@Edge suits heavier logic needing more runtime or resources; Step Functions and Glue are unrelated to edge request processing.$q$),
('sa-q-448','awssaa',3,'3.4','mcq',1,$q$A CloudFront distribution serves large JSON API responses to users on slow mobile connections, and the team wants to reduce transfer size and load time without any origin-side changes. What should they enable?$q$,$q$["CloudFront automatic compression (Gzip/Brotli)","S3 Transfer Acceleration","A Network Load Balancer","Route 53 latency routing"]$q$::jsonb,'0'::jsonb,$q$CloudFront's automatic compression shrinks eligible text-based responses at the edge before delivery, cutting transfer size and latency with no origin changes needed. The other options address S3 uploads, load balancing, and DNS routing - not response compression.$q$),
('sa-q-449','awssaa',3,'3.4','mcq',2,$q$A live-streaming platform needs to place video-encoding compute physically closer to viewers in a specific metro area than the nearest full AWS Region, to cut end-to-end latency. What should they use?$q$,$q$["An AWS Local Zone","AWS Wavelength","A second full AWS Region","CloudFront Functions"]$q$::jsonb,'0'::jsonb,$q$Local Zones extend compute and storage to metro areas outside a full Region, putting resources physically nearer to end users for latency-sensitive workloads like live streaming or gaming. Wavelength specifically targets telco 5G networks for mobile traffic, a second full Region is a much bigger commitment, and CloudFront Functions only run lightweight edge logic, not video encoding.$q$),
('sa-q-450','awssaa',3,'3.4','mcq',3,$q$A mobile game publisher wants application traffic from 5G phones to reach AWS compute without ever leaving the mobile carrier's network, minimizing latency for real-time gameplay. Which service is purpose-built for this?$q$,$q$["AWS Local Zones","AWS Wavelength","AWS Direct Connect","Amazon CloudFront"]$q$::jsonb,'1'::jsonb,$q$Wavelength embeds AWS compute and storage inside telecom providers' 5G networks so mobile traffic never has to leave the carrier network to reach AWS resources - the specific mobile-edge latency case described. Local Zones target metro areas generally (not embedded in carrier networks), and Direct Connect/CloudFront solve different connectivity problems.$q$),
('sa-q-451','awssaa',3,'3.4','matching',2,$q$Match each networking feature to its description.$q$,$q${"left":["Network Load Balancer cross-zone load balancing","AWS Direct Connect Gateway","Route 53 Resolver endpoints","AWS Global Accelerator"],"right":["Trade-off between even traffic distribution across AZs and preserving each AZ's low-latency locality","Extends a single Direct Connect connection to reach VPCs in multiple AWS accounts and regions","Enable DNS query resolution between a VPC and on-premises networks","Static Anycast IPs routing TCP/UDP traffic over the AWS global backbone to the nearest healthy endpoint"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Cross-zone load balancing on an NLB trades even distribution against cross-AZ locality; a Direct Connect Gateway lets one physical connection reach many VPCs across accounts/regions instead of just one; Resolver endpoints extend DNS resolution between on-premises and VPC DNS; Global Accelerator front-ends TCP/UDP traffic with static Anycast IPs over AWS's backbone.$q$),
('sa-q-452','awssaa',3,'3.4','ordering',3,$q$Order these ways of reaching an AWS-hosted resource from MOST to LEAST latency-optimized for a repeat request.$q$,$q$["A CloudFront cache hit served directly from the nearest edge location","AWS Global Accelerator routing over the AWS backbone to the origin (no caching)","AWS Direct Connect carrying the request from an on-premises data center to the origin","A standard request routed over the public internet to the origin"]$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$A CloudFront cache hit never leaves the edge location, so it's fastest; Global Accelerator still reaches all the way to the origin but travels AWS's optimized backbone rather than the public internet; Direct Connect is a dedicated private link but originates from a fixed on-premises location rather than the nearest edge to an arbitrary end user; a standard public-internet path is subject to the most variable routing and congestion.$q$),
-- 3.5 High-Performing Data Ingestion/Transformation
('sa-q-453','awssaa',3,'3.5','mcq',2,$q$A producer writes about 1,500 records per second (roughly 700 KB/s total) into a Kinesis Data Stream. Based on per-shard limits, what is the minimum number of shards needed?$q$,$q$["1 shard, since 700 KB/s is under the 1 MB/s limit","2 shards, since 1,500 records/s exceeds the 1,000 records/s per-shard limit even though the byte rate is fine","2 shards, because Kinesis always requires an even number","4 shards, since each shard maxes out at 500 records/s"]$q$::jsonb,'1'::jsonb,$q$Each shard supports the lower of 1 MB/s or 1,000 records/s of writes; here the byte rate (700 KB/s) fits in one shard, but the record count (1,500/s) exceeds one shard's 1,000 records/s ceiling, so at least 2 shards are needed to satisfy the more restrictive limit.$q$),
('sa-q-454','awssaa',3,'3.5','mcq',2,$q$After a downstream consumer crashes and is redeployed several hours later, the team needs to reprocess records that arrived during the outage rather than losing them. Which Kinesis Data Streams setting makes this possible?$q$,$q$["The default 24-hour (or longer, up to 365 days) retention period, allowing replay","Kinesis has no retention; once read, records are gone","Enabling S3 versioning on the stream","Switching the stream to Firehose retroactively"]$q$::jsonb,'0'::jsonb,$q$Kinesis Data Streams retains records for a configurable window (24 hours by default, extendable up to 365 days), so a consumer can resume from an earlier point and reprocess data it missed, unlike a queue where a message disappears once consumed. S3 versioning and Firehose don't apply to an existing Data Streams retention window.$q$),
('sa-q-455','awssaa',3,'3.5','mcq',3,$q$Three independent applications each need to consume the full throughput of every shard in a Kinesis Data Stream in real time, and none should be throttled by the others' read activity. What should be configured?$q$,$q$["Enhanced fan-out registered consumers for each application","A single shared consumer that all three applications poll","Kinesis Data Firehose instead of Data Streams","Reducing the stream to one shard so there's less to share"]$q$::jsonb,'0'::jsonb,$q$Enhanced fan-out gives each registered consumer its own dedicated 2 MB/s per shard over a push-based HTTP/2 connection, so multiple consumers don't compete for one shard's shared 2 MB/s read throughput. A shared consumer setup, switching to Firehose, or shrinking the stream would not give each application independent full-throughput access.$q$),
('sa-q-456','awssaa',3,'3.5','mcq',1,$q$A team needs streaming data delivered reliably into S3 for later analysis and does not want to write or operate any consumer application, shard management, or scaling logic. Which service fits best?$q$,$q$["Kinesis Data Streams with a custom consumer","Kinesis Data Firehose","Amazon SQS with manual polling","Amazon EMR"]$q$::jsonb,'1'::jsonb,$q$Firehose is a fully managed delivery service - point it at S3 and it handles buffering, batching, and delivery automatically with no consumer code or shard management. Data Streams requires you to build the consumer, SQS is a queue rather than a stream-delivery service, and EMR is a processing cluster, not an ingestion pipeline.$q$),
('sa-q-457','awssaa',3,'3.5','mcq',2,$q$A Firehose delivery stream is configured with a large buffer size and a long buffer interval, and the team notices records take several minutes to appear in the destination, though each delivered batch is efficiently sized. What is the trade-off being made?$q$,$q$["Higher end-to-end latency in exchange for more efficient, larger delivery batches","Lower cost with no effect on latency at all","Firehose ignores buffer settings for S3 destinations","Data loss risk increases with larger buffers"]$q$::jsonb,'0'::jsonb,$q$Firehose batches records until either the buffer size or buffer interval threshold is reached, whichever comes first; larger/longer buffer settings improve delivery efficiency (fewer, bigger batches) at the direct cost of higher latency before data appears at the destination. Buffer settings do apply to S3 destinations, and Firehose doesn't lose data because of buffering.$q$),
('sa-q-458','awssaa',3,'3.5','mcq',2,$q$A Firehose delivery stream receives events as raw JSON, but the destination data lake expects columnar Parquet format for efficient querying. How can this conversion happen automatically as part of ingestion?$q$,$q$["It cannot; a separate batch job must convert the files after delivery","Configure a Firehose data transformation step that invokes Lambda before delivery","Enable Kinesis Data Streams enhanced fan-out","Switch the destination to DynamoDB, which stores Parquet natively"]$q$::jsonb,'1'::jsonb,$q$Firehose can invoke a Lambda function to transform each batch of records - including format conversion - before delivering it to the destination, avoiding a separate post-processing job. Enhanced fan-out is a Data Streams consumer feature, and DynamoDB doesn't store Parquet.$q$),
('sa-q-459','awssaa',3,'3.5','mcq',2,$q$A team wants to run a continuous SQL aggregation (a rolling 5-minute average) directly against a live Kinesis Data Stream, without standing up and operating their own stream-processing cluster. Which service fits?$q$,$q$["Amazon Kinesis Data Analytics (Managed Service for Apache Flink)","AWS Glue crawler","AWS Data Pipeline","Amazon Redshift Spectrum"]$q$::jsonb,'0'::jsonb,$q$Kinesis Data Analytics runs real-time SQL or Flink applications directly against a stream, computing rolling aggregates without you managing any processing cluster. A Glue crawler only discovers schema, Data Pipeline orchestrates scheduled batch movement, and Redshift Spectrum queries S3 data, not live streams.$q$),
('sa-q-460','awssaa',3,'3.5','mcq',2,$q$Traffic into a Kinesis Data Stream has grown well beyond what its current shard count can absorb, causing writes to be throttled. What should be done to increase capacity while keeping the stream running?$q$,$q$["Delete and recreate the stream with more shards","Reshard by splitting shards to increase the shard count","Switch to SQS, which has no shard concept","Enable S3 Versioning on the stream's data"]$q$::jsonb,'1'::jsonb,$q$Resharding (splitting shards) increases a running stream's shard count and therefore its throughput ceiling without deleting or recreating the stream. Deleting and recreating loses continuity, SQS solves a different problem, and S3 versioning is unrelated to Kinesis capacity.$q$),
('sa-q-461','awssaa',3,'3.5','mcq',1,$q$A team has raw log files landing in S3 with an evolving schema and wants those files queryable through Amazon Athena without hand-writing table definitions every time the schema changes. What combination should they use?$q$,$q$["An AWS Glue crawler to populate the Glue Data Catalog automatically","Manually writing a new CREATE TABLE statement in Athena after every schema change","AWS Data Pipeline alone, with no catalog","Amazon Redshift instead of Athena"]$q$::jsonb,'0'::jsonb,$q$A Glue crawler scans the S3 data, infers schema and partitions, and keeps the Glue Data Catalog updated automatically, so Athena can query it as a table without manual definitions. Manual CREATE TABLE statements don't scale with schema drift, Data Pipeline doesn't provide a catalog, and switching engines doesn't solve the schema-discovery problem.$q$),
('sa-q-462','awssaa',3,'3.5','mcq',2,$q$A Glue ETL job runs nightly against an S3 bucket that only receives a handful of new files each day, but the job currently reprocesses every historical file every run, wasting time and cost. What Glue feature fixes this?$q$,$q$["Glue DataBrew","Glue Job Bookmarks","Glue Data Catalog alone","Increasing the job's worker count"]$q$::jsonb,'1'::jsonb,$q$Job Bookmarks track which source data has already been processed, so subsequent runs process only new or changed data instead of reprocessing the entire history. DataBrew is a visual data-prep tool, the Data Catalog alone doesn't track processing state, and adding workers just makes the wasteful full reprocessing faster, not smaller.$q$),
('sa-q-463','awssaa',3,'3.5','mcq',1,$q$A business analyst with no coding background needs to explore, clean, and normalize a messy CSV dataset in S3 before it's used in a pipeline. Which AWS tool fits best?$q$,$q$["AWS Glue DataBrew","AWS Glue Studio Spark jobs","Amazon EMR with a custom Spark script","AWS Step Functions"]$q$::jsonb,'0'::jsonb,$q$DataBrew provides a visual, no-code interface for exploring and cleaning data, purpose-built for analysts without a coding background. The other options require writing Spark code or defining state machines.$q$),
('sa-q-464','awssaa',3,'3.5','mcq',2,$q$A team maintains a long-running, legacy scheduled job that copies data from an on-premises database to S3 nightly, originally built years ago on AWS Data Pipeline. For a NEW pipeline being designed today, which is generally the more current, recommended approach?$q$,$q$["Continue using AWS Data Pipeline for all new pipelines, since it's still AWS's primary orchestration recommendation","Design new pipelines with services like AWS Glue workflows or Step Functions, treating Data Pipeline as a legacy option","AWS Data Pipeline is only usable for streaming, not batch, workloads","AWS Data Pipeline has been fully removed from AWS and cannot run at all"]$q$::jsonb,'1'::jsonb,$q$Data Pipeline still exists and can be tested as a legacy orchestration service, but AWS's current guidance for new designs favors Glue workflows or Step Functions for orchestrating data movement and transformation. It was originally built for batch data movement (not exclusively streaming), and it has not been removed from the platform.$q$),
('sa-q-465','awssaa',3,'3.5','mcq',2,$q$A company is migrating from an on-premises database to Amazon Aurora and, after the initial cutover, wants ongoing changes from the old system to keep flowing into Aurora in near real time during a transition period. What AWS DMS capability enables this?$q$,$q$["A one-time full load only, with no ongoing sync option","Full load plus change data capture (CDC) for continuous replication of ongoing changes","AWS DMS only supports migrations between two AWS-hosted databases","Manual nightly export/import scripts"]$q$::jsonb,'1'::jsonb,$q$DMS supports an initial full load followed by CDC-based replication that continuously streams ongoing source changes to the target, ideal for a transition period or as a near-real-time ingestion pipeline. DMS is not limited to a one-time load, and it explicitly supports on-premises-to-AWS migrations, not just AWS-to-AWS.$q$),
('sa-q-466','awssaa',3,'3.5','multi',2,$q$Which of the following statements about Amazon MSK (Managed Streaming for Apache Kafka) are true? (Select all that apply.)$q$,$q$["It is a fully managed service for running Apache Kafka clusters","It is API-compatible with open-source Kafka, so existing Kafka tooling and clients can be reused","It replaces the need for any consumer application code, similar to Firehose","It is a reasonable choice for a team already standardized on the Kafka ecosystem"]$q$::jsonb,$q$[0,1,3]$q$::jsonb,$q$MSK manages the operational burden of running Kafka (broker provisioning, patching, scaling) while remaining Kafka-API-compatible, so existing Kafka producers/consumers and tooling work largely unchanged - making it attractive for teams already invested in Kafka. Unlike Firehose, MSK is a streaming platform, not a managed delivery service, so consumer applications still need to be built and run.$q$),
('sa-q-467','awssaa',3,'3.5','mcq',2,$q$A data engineering team needs to run large-scale Spark and Hadoop transformation jobs against many terabytes of historical data stored in S3, with full control over cluster configuration and the ability to use custom big-data frameworks. Which service fits best?$q$,$q$["Amazon EMR","AWS Glue DataBrew","Amazon Kinesis Data Firehose","AWS Step Functions"]$q$::jsonb,'0'::jsonb,$q$EMR provisions managed Hadoop/Spark (and other big-data framework) clusters with full configuration control, suited to large-scale custom transformation jobs against S3 data. DataBrew is no-code and lighter-weight, Firehose only delivers streaming data, and Step Functions orchestrates workflows rather than running big-data processing itself.$q$),
('sa-q-468','awssaa',3,'3.5','mcq',2,$q$A Firehose delivery stream ingests clickstream events tagged with a "customer_id" field, and the team wants the data automatically organized into separate S3 prefixes per customer as it arrives, without a separate post-processing job. What Firehose feature enables this?$q$,$q$["Dynamic partitioning based on data content","A larger buffer size","Kinesis enhanced fan-out","Firehose compression"]$q$::jsonb,'0'::jsonb,$q$Firehose dynamic partitioning groups streaming data by keys derived from record content (like customer_id) and writes it into corresponding S3 prefixes in near real time, avoiding a separate ETL job to reorganize the data afterward. Buffer size affects batching timing, enhanced fan-out is a Data Streams consumer feature, and compression just shrinks file size.$q$),
('sa-q-469','awssaa',3,'3.5','matching',3,$q$Match each service to the ingestion or orchestration role it plays.$q$,$q${"left":["AWS Snowball","AWS Step Functions","Kinesis Client Library (KCL)","Amazon EMR"],"right":["A physical, ruggedized device for offline transfer of very large datasets into AWS when network transfer would be impractically slow","Orchestrates a multi-step ETL workflow with retries and error handling","Tracks shard assignment and checkpoint progress for custom Kinesis Data Streams consumers","Runs large-scale distributed Spark/Hadoop transformation jobs"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Snowball physically ships large datasets into AWS when bandwidth would make network transfer impractical; Step Functions coordinates multi-step workflows with built-in retry/error handling; KCL handles shard discovery and checkpointing bookkeeping for custom stream consumers; EMR runs the actual large-scale distributed processing.$q$),
('sa-q-470','awssaa',3,'3.5','ordering',2,$q$Order the stages of a typical AWS Glue-based batch ETL flow, from FIRST to LAST.$q$,$q$["A Glue crawler scans S3 and populates the Glue Data Catalog with the discovered schema","A Glue ETL job reads the cataloged data and transforms it with Spark","Glue Job Bookmarks record which source data has been processed","The transformed data is queried through Athena or Redshift Spectrum using the catalog"]$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$The crawler must discover and catalog the schema before a job can read the data by table reference; the job transforms the data and, as it finishes, bookmarks record progress so the next run skips already-processed data; only after transformation is the resulting data typically queried downstream via Athena or Redshift Spectrum.$q$);
